#!/usr/bin/env ruby
require'json';require'fileutils';root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);common=File.join(client,'assets/Common');compat=File.join(common,'Code/Runtime/CompatibilityApp');catalog=File.readlines(File.join(root,'server/Bootstrap/src/main/resources/game-catalog-528.tsv'),chomp:true).drop(1).map{|l|l.split("\t")[1].downcase};dirs=Dir.glob(File.join(compat,'*')).select{|p|File.directory?(p)};rows=dirs.map{|p|name=File.basename(p);files=Dir.glob(File.join(p,'**/*')).count{|f|File.file?(f)};{name:name,files:files,classification:catalog.include?(name.downcase)?'CONCRETE_GAME':'PLATFORM_OR_UNRESOLVED'}};game=rows.select{|r|r[:classification]=='CONCRETE_GAME'};report={schemaVersion:1,commonFiles:Dir.glob(File.join(common,'**/*')).count{|f|File.file?(f)},compatibilityDomains:rows,concreteGamesInCommon:game,checks:{noConcreteGamesInCommon:game.empty?,boundedCommon:false},verdict:'blocked-common-boundary'};out=File.join(root,'docs/generated/creal01-common-growth.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");puts "CREAL01 AUDITED: #{game.length} concrete game directories remain in Common"
